package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

type Matrix [][]int64

func newMatrix(n int) Matrix {
	m := make(Matrix, n)
	for i := range m {
		m[i] = make([]int64, n)
	}
	return m
}

func multiply(a, b Matrix) Matrix {
	n := len(a)
	c := newMatrix(n)
	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				if b[k][j] == 0 {
					continue
				}
				c[i][j] += a[i][k] * b[k][j] % MOD
				if c[i][j] >= MOD {
					c[i][j] -= MOD
				}
			}
		}
	}
	return c
}

func power(a Matrix, e int64) Matrix {
	n := len(a)
	res := newMatrix(n)
	for i := 0; i < n; i++ {
		res[i][i] = 1
	}
	for e > 0 {
		if e&1 == 1 {
			res = multiply(res, a)
		}
		a = multiply(a, a)
		e >>= 1
	}
	return res
}

func trace(a Matrix) int64 {
	var res int64
	for i := range a {
		res += a[i][i]
		if res >= MOD {
			res -= MOD
		}
	}
	return res
}

func addTransition(m Matrix, from, to int) {
	m[from][to]++
	if m[from][to] == MOD {
		m[from][to] = 0
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	const states = 16
	t := newMatrix(states)

	for occ := 0; occ < 4; occ++ {
		b0 := occ & 1
		b1 := (occ >> 1) & 1

		for flags := 0; flags < 4; flags++ {
			from := occ*4 + flags

			if b0 != 0 {
				for decoration := 0; decoration < 4; decoration++ {
					if decoration&flags != 0 {
						continue
					}
					nextFlags := flags | decoration
					nextOcc := b1
					to := nextOcc*4 + nextFlags
					addTransition(t, from, to)
				}
				continue
			}

			if flags == 3 {
				nextOcc := b1
				to := nextOcc * 4
				addTransition(t, from, to)
			}

			for decoration := 0; decoration < 4; decoration++ {
				if decoration&flags != 0 {
					continue
				}
				nextFlags := flags | decoration

				if b1 == 0 {
					nextOcc := 1
					to := nextOcc*4 + nextFlags
					addTransition(t, from, to)
				}

				nextOcc := b1 | 2
				to := nextOcc*4 + nextFlags
				addTransition(t, from, to)
			}
		}
	}

	p := newMatrix(4)
	for occ := 0; occ < 4; occ++ {
		b0 := occ & 1
		b1 := (occ >> 1) & 1

		if b0 != 0 {
			addTransition(p, occ, b1)
		} else {
			if b1 == 0 {
				addTransition(p, occ, 1)
			}
			addTransition(p, occ, b1|2)
		}
	}

	total := trace(power(t, n))
	withoutOpposite := trace(power(p, n))
	answer := (total - 4*withoutOpposite%MOD + MOD) % MOD

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

func trim(a []int64) []int64 {
	for len(a) > 1 && a[len(a)-1] == 0 {
		a = a[:len(a)-1]
	}
	return a
}

func mul(a, b []int64) []int64 {
	res := make([]int64, len(a)+len(b)-1)
	for i, x := range a {
		if x == 0 {
			continue
		}
		for j, y := range b {
			res[i+j] = (res[i+j] + x*y) % MOD
		}
	}
	return trim(res)
}

func sub(a, b []int64) []int64 {
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	res := make([]int64, n)
	for i := 0; i < n; i++ {
		if i < len(a) {
			res[i] = a[i]
		}
		if i < len(b) {
			res[i] -= b[i]
			if res[i] < 0 {
				res[i] += MOD
			}
		}
	}
	return trim(res)
}

func truncate(a []int64, n int) []int64 {
	if len(a) > n {
		a = a[:n]
	}
	res := make([]int64, len(a))
	copy(res, a)
	return trim(res)
}

func logDerivativeCoefficient(h []int64, index int) int64 {
	g := make([]int64, index+1)
	for k := 0; k <= index; k++ {
		var value int64
		if k+1 < len(h) {
			value = int64(k+1) * h[k+1] % MOD
		}
		limit := k
		if len(h)-1 < limit {
			limit = len(h) - 1
		}
		for i := 1; i <= limit; i++ {
			value = (value - h[i]*g[k-i]) % MOD
		}
		if value < 0 {
			value += MOD
		}
		g[k] = value
	}
	return g[index]
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	r := []int64{1, 0, MOD - 1, 0, MOD - 1}
	q := mul(mul(r, r), r)

	const capDegree = 12
	p := make([]int64, capDegree+1)
	p[0] = 1
	p[2] = 1
	for i := 4; i <= capDegree; i += 2 {
		p[i] = (p[i-2] + p[i-4]) % MOD
	}

	aSeries := make([]int64, capDegree+1)
	bSeries := make([]int64, capDegree+1)
	cSeries := make([]int64, capDegree+1)

	for l := 1; l+1 <= capDegree; l++ {
		idx := l + 1
		l2 := int64(l*l) % MOD
		aSeries[idx] = l2 * p[l] % MOD
		bSeries[idx] = l2 * p[l-1] % MOD
		if l >= 2 {
			cSeries[idx] = l2 * p[l-2] % MOD
		}
	}

	a := truncate(mul(q, aSeries), capDegree+1)
	b := truncate(mul(q, bSeries), capDegree+1)
	c := truncate(mul(q, cSeries), capDegree+1)

	qa := sub(q, a)
	qc := sub(q, c)

	numerator := sub(mul(qa, qc), mul(b, b))
	denominator := mul(q, q)

	gDen := logDerivativeCoefficient(denominator, n-1)
	gNum := logDerivativeCoefficient(numerator, n-1)

	answer := gDen - gNum
	if answer < 0 {
		answer += MOD
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

