const MOD int64 = 998244353
const SZ = 12

type Matrix12 [SZ][SZ]int64
type Matrix4 [4][4]int64

func mul12(a, b Matrix12) Matrix12 {
	var c Matrix12
	for i := 0; i < SZ; i++ {
		for k := 0; k < SZ; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < SZ; j++ {
				if b[k][j] != 0 {
					c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % MOD
				}
			}
		}
	}
	return c
}

func pow12(a Matrix12, n int) Matrix12 {
	var r Matrix12
	for i := 0; i < SZ; i++ {
		r[i][i] = 1
	}
	for n > 0 {
		if n&1 == 1 {
			r = mul12(r, a)
		}
		a = mul12(a, a)
		n >>= 1
	}
	return r
}

func mul4(a, b Matrix4) Matrix4 {
	var c Matrix4
	for i := 0; i < 4; i++ {
		for k := 0; k < 4; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < 4; j++ {
				if b[k][j] != 0 {
					c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % MOD
				}
			}
		}
	}
	return c
}

func pow4(a Matrix4, n int) Matrix4 {
	var r Matrix4
	for i := 0; i < 4; i++ {
		r[i][i] = 1
	}
	for n > 0 {
		if n&1 == 1 {
			r = mul4(r, a)
		}
		a = mul4(a, a)
		n >>= 1
	}
	return r
}

func addTensorTransition(a *Matrix12, fromMask, toMask int, g [3][3]int64) {
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			if g[i][j] != 0 {
				x := fromMask*3 + i
				y := toMask*3 + j
				a[x][y] = (a[x][y] + g[i][j]) % MOD
			}
		}
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	nonMonomer := [3][3]int64{
		{1, 0, 0},
		{1, 1, 0},
		{1, 2, 1},
	}
	monomer := [3][3]int64{
		{0, 0, 1},
		{0, 0, 0},
		{0, 0, 0},
	}

	var a Matrix12
	var b Matrix4

	for mask := 0; mask < 4; mask++ {
		if mask&1 != 0 {
			to := mask >> 1
			addTensorTransition(&a, mask, to, nonMonomer)
			b[mask][to]++
			continue
		}

		toMonomer := mask >> 1
		addTensorTransition(&a, mask, toMonomer, monomer)

		if mask&2 == 0 {
			to := (mask >> 1) | 1
			addTensorTransition(&a, mask, to, nonMonomer)
			b[mask][to]++
		}

		to := (mask >> 1) | 2
		addTensorTransition(&a, mask, to, nonMonomer)
		b[mask][to]++
	}

	an := pow12(a, n)
	var total int64
	for i := 0; i < SZ; i++ {
		total = (total + an[i][i]) % MOD
	}

	bn := pow4(b, n)
	var noMonomer int64
	for i := 0; i < 4; i++ {
		noMonomer = (noMonomer + bn[i][i]) % MOD
	}

	answer := (total - 3*noMonomer) % MOD
	if answer < 0 {
		answer += MOD
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}

