			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				if b[k][j] == 0 {
					continue
				}
				c[i][j] = (c[i][j] + a[i][k]*b[k][j]) % mod
			}
		}
	}
	return c
}

func power(a Matrix, exponent int) Matrix {
	n := len(a)
	result := newMatrix(n)
	for i := 0; i < n; i++ {
		result[i][i] = 1
	}

	for exponent > 0 {
		if exponent&1 == 1 {
			result = multiply(result, a)
		}
		a = multiply(a, a)
		exponent >>= 1
	}
	return result
}

func trace(a Matrix) int64 {
	var result int64
	for i := range a {
		result += a[i][i]
		if result >= mod {
			result -= mod
		}
	}
	return result
