func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	nonDiameter := Matrix{
		{1, 1, 0},
		{0, 1, 1},
		{0, 0, 1},
	}
	diameter := Matrix{
		{0, 0, 0},
		{1, 0, 0},
		{2, 0, 0},
	}

	full := newMatrix(12)
	noDiameter := newMatrix(4)

	addTransition := func(from, to int, symbol Matrix, includeNoDiameter bool) {
		for i := 0; i < 3; i++ {
			for j := 0; j < 3; j++ {
				r := from*3 + i
				c := to*3 + j
				full[r][c] = (full[r][c] + symbol[i][j]) % mod
			}
		}
		if includeNoDiameter {
			noDiameter[from][to]++
		}
	}

	for state := 0; state < 4; state++ {
		currentOccupied := state & 1
		nextOccupied := (state >> 1) & 1

		if currentOccupied == 1 {
			nextState := nextOccupied
			addTransition(state, nextState, nonDiameter, true)
			continue
		}

		// Place a diameter at the current position.
		addTransition(state, nextOccupied, diameter, false)

		// Pair with the next position.
		if nextOccupied == 0 {
			addTransition(state, 1, nonDiameter, true)
		}

		// Pair with the position two steps ahead.
		addTransition(state, nextOccupied|2, nonDiameter, true)
	}

	total := trace(power(full, n))
	withoutDiameters := trace(power(noDiameter, n))

	answer := (total - 3*withoutDiameters) % mod
	if answer < 0 {
		answer += mod
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
