package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 998244353

type Matrix struct {
	n int
	a []int64
}

func newMatrix(n int) Matrix {
	return Matrix{n: n, a: make([]int64, n*n)}
}

func identityMatrix(n int) Matrix {
	m := newMatrix(n)
	for i := 0; i < n; i++ {
		m.a[i*n+i] = 1
	}
	return m
}

func multiply(x, y Matrix) Matrix {
	n := x.n
	z := newMatrix(n)
	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			xv := x.a[i*n+k]
			if xv == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				yv := y.a[k*n+j]
				if yv == 0 {
					continue
				}
				idx := i*n + j
				z.a[idx] = (z.a[idx] + xv*yv) % mod
			}
		}
	}
	return z
}

func power(base Matrix, exp int) Matrix {
	res := identityMatrix(base.n)
	for exp > 0 {
		if exp&1 == 1 {
			res = multiply(res, base)
		}
		base = multiply(base, base)
		exp >>= 1
	}
	return res
}

func trace(m Matrix) int64 {
	var res int64
	for i := 0; i < m.n; i++ {
		res += m.a[i*m.n+i]
		if res >= mod {
			res -= mod
		}
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	A := [3][3]int64{
		{1, 0, 0},
		{1, 1, 0},
		{1, 2, 1},
	}
	B := [3][3]int64{}
	B[0][2] = 1

	T := newMatrix(12)
	P := newMatrix(4)

	addTensorTransition := func(from, to int, w [3][3]int64) {
		for i := 0; i < 3; i++ {
			for j := 0; j < 3; j++ {
				if w[i][j] == 0 {
					continue
				}
				r := from*3 + i
				c := to*3 + j
				T.a[r*12+c] += w[i][j]
				T.a[r*12+c] %= mod
			}
		}
	}

	addNonMonomer := func(from, to int) {
		P.a[from*4+to]++
		if P.a[from*4+to] >= mod {
			P.a[from*4+to] -= mod
		}
		addTensorTransition(from, to, A)
	}

	for s := 0; s < 4; s++ {
		if s&1 != 0 {
			addNonMonomer(s, s>>1)
			continue
		}

		// A diameter pair (a removed/opposite flower pair).
		addTensorTransition(s, s>>1, B)

		// Pair the current position with the next one.
		if s&2 == 0 {
			addNonMonomer(s, 1)
		}

		// Pair the current position with the position two steps ahead.
		addNonMonomer(s, (s>>1)|2)
	}

	total := trace(power(T, n))
	withoutDiameters := trace(power(P, n))
	answer := (total - 3*withoutDiameters) % mod
	if answer < 0 {
		answer += mod
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, answer)
	out.Flush()
}
